CREATE TABLE "orchestrator_settings" ("id" integer PRIMARY KEY DEFAULT 1 NOT NULL, "harness" "harness" DEFAULT 'codex' NOT NULL, "model" text DEFAULT 'gpt-5' NOT NULL, "reasoning" text DEFAULT 'medium' NOT NULL, "system_prompt" text DEFAULT 'You supervise engineering workflows. Use only supplied state and be concise.' NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "conversations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "project_path" text NOT NULL, "task_id" uuid, "run_id" uuid, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "conversation_messages" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "conversation_id" uuid NOT NULL REFERENCES "conversations"("id"), "role" text NOT NULL, "content" text NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, CONSTRAINT "conversation_messages_role_check" CHECK ("conversation_messages"."role" in ('user', 'assistant')));
CREATE TABLE "domain_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "type" text NOT NULL, "project_path" text NOT NULL, "task_id" uuid, "run_id" uuid, "agent_execution_id" uuid, "data" jsonb DEFAULT '{}'::jsonb NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE INDEX "domain_events_run_id_created_at_idx" ON "domain_events" USING btree ("run_id","created_at");
